steps.code:
# Let's query all expenses for each group without date filter to see all expenses
all_expenses = {}
for group in groups_list:
    gid = group['group_id']
    expenses = apis.splitwise.show_group_expenses(
        group_id=gid,
        access_token=splitwise_login['access_token'],
        page_limit=20
    )
    all_expenses[gid] = expenses
    print(f"Group {gid} ({group['name']}): {len(expenses)} expenses")
    for exp in expenses:
        print(exp)

